                    height: inputs.mediaHeight)
            }
        }
        if let key {
            lock.lock()
            let hit = memo[key]
            lock.unlock()
            if let hit { return hit.value }
        }
        var value: (Double, Double)?
        if let pack = try? MaskPack(contentsOf: inputs.pack),
            let point = (try? CutoutStatus.centroid(
